; ==================================================================
; MAIN PROGRAM (KONAMI CARTRIDGE)
; ==================================================================

MAIN_GAME_START:
    ; Set screen mode for game
    LD A, 2              ; Screen 2 for MSX1
    CALL CHGMOD

    ; Clear screen
    CALL CLS

    ; Initialize game systems
    CALL INIT_GAME_SYSTEMS

    ; Initialize Game Flow system inline (avoid forward reference)
    XOR A
    LD (current_flow_state), A
    LD (prev_flow_state), A

    ; Start with main menu
    LD A, FLOW_STATE_MAIN_MENU
    LD (current_flow_state), A

    ; Main game loop
MAIN_LOOP:
    HALT                 ; Wait for V-Blank

    ; Update current game state
    CALL UPDATE_CURRENT_STATE

    ; Handle input
    CALL HANDLE_INPUT

    ; Update game systems
    CALL UPDATE_GAME_SYSTEMS

    ; Render frame
    CALL RENDER_FRAME

    ; Loop forever
    JP MAIN_LOOP


; ==================================================================
; GAME FLOW SYSTEM
; ==================================================================

; Game Flow State Constants
FLOW_STATE_MAIN_MENU    EQU 0
FLOW_STATE_GAME         EQU 1
FLOW_STATE_GAME_OVER    EQU 2

CHANGE_FLOW_STATE:
    ; Change Game Flow state
    ; A = new state
    LD (current_flow_state), A
    RET

; Variables defined in EQU section above - no DB needed in ROM

; ==================================================================
; GAME SYSTEMS (DYNAMIC GENERATION)
; Only systems needed for this project are included
; ==================================================================

INIT_GAME_SYSTEMS:
    ; Initialize systems dynamically based on project assets
    CALL INIT_INPUT_SYSTEM    ; Always needed
    CALL INIT_SPRITE_SYSTEM   ; Project has 1 sprites
    CALL INIT_TILE_SYSTEM     ; Project has 2 tiles
    CALL INIT_SCREEN_SYSTEM   ; Project has 1 screens
    CALL INIT_COLLISION_SYSTEM ; Project has collision layers
    RET

INIT_INPUT_SYSTEM:
    ; Initialize input handling
    XOR A
    LD (input_state), A
    LD (prev_input_state), A
    RET

INIT_SPRITE_SYSTEM:
    ; Initialize sprite system for 1 sprites
    ; NOTE: Individual sprite patterns are loaded by name
    ; Use SPRITE_[NAME]_F[FRAME]_C[COLOR]_LAYER labels generated by sprite assets
    ; Clear sprite attributes table
    LD HL, SPRATR
    LD DE, SPRATR+1
    LD BC, 127      ; Clear all 32 sprites × 4 bytes = 128 bytes
    LD (HL), #D1    ; Y=209 (off-screen position)
    LDIR
    ; Initialize sprite counter
    XOR A
    LD (active_sprite_count), A
    RET

INIT_TILE_SYSTEM:
    ; Initialize MSX Screen 2 tile system with 3 banks
    ; Load all 3 pattern banks to their VRAM locations
    CALL LOAD_PATTERN_BANK0       ; Bank 0 (Lines 0-7)
    CALL LOAD_PATTERN_BANK1       ; Bank 1 (Lines 8-15)
    CALL LOAD_PATTERN_BANK2       ; Bank 2 (Lines 16-23)
    ; Load all 3 color banks to their VRAM locations
    CALL LOAD_COLOR_BANK0         ; Bank 0 colors
    CALL LOAD_COLOR_BANK1         ; Bank 1 colors
    CALL LOAD_COLOR_BANK2         ; Bank 2 colors
    RET

; MSX Screen 2 Bank Loading Functions
LOAD_PATTERN_BANK0:
    ; Load pattern bank 0 to VRAM (base patterns)
    LD HL, TILE_PATTERN_BANK0
    LD DE, CHRTBL2                ; VRAM pattern table bank 0 (base)
    LD BC, 256 * 8                ; Max 256 patterns × 8 bytes
    CALL LDIRVM                   ; Use BIOS function
    RET

LOAD_PATTERN_BANK1:
    ; Load pattern bank 1: same patterns as bank 0 (Mideas standard)
    LD HL, TILE_PATTERN_BANK0     ; Same source as Bank 0
    LD DE, CHRTBL2 + #800         ; VRAM pattern table bank 1 (+#800 offset)
    LD BC, 256 * 8                ; Max 256 patterns × 8 bytes
    CALL LDIRVM                   ; Use BIOS function
    RET

LOAD_PATTERN_BANK2:
    ; MSX Screen 2 Bank 2: Load same patterns as other banks (Mideas standard)
    LD HL, TILE_PATTERN_BANK0     ; Same source as Bank 0
    LD DE, CHRTBL2 + #1000        ; VRAM pattern table bank 2 (+#1000 offset)
    LD BC, 256 * 8                ; Max 256 patterns × 8 bytes
    CALL LDIRVM                   ; Use BIOS function like real Mideas
    RET

LOAD_COLOR_BANK0:
    ; Load color bank 0 to VRAM (base colors)
    LD HL, TILE_COLOR_BANK0
    LD DE, CLRTBL2                ; VRAM color table bank 0 (base)
    LD BC, 256 * 8                ; Max 256 patterns × 8 bytes
    CALL LDIRVM                   ; Use BIOS function
    RET

LOAD_COLOR_BANK1:
    ; Load color bank 1: same colors as bank 0 (Mideas standard)
    LD HL, TILE_COLOR_BANK0       ; Same source as Bank 0
    LD DE, CLRTBL2 + #800         ; VRAM color table bank 1 (+#800 offset)
    LD BC, 256 * 8                ; Max 256 patterns × 8 bytes
    CALL LDIRVM                   ; Use BIOS function
    RET

LOAD_COLOR_BANK2:
    ; Load color bank 2: same colors as other banks (Mideas standard)
    LD HL, TILE_COLOR_BANK0       ; Same source as Bank 0
    LD DE, CLRTBL2 + #1000        ; VRAM color table bank 2 (+#1000 offset)
    LD BC, 256 * 8                ; Max 256 patterns × 8 bytes
    CALL LDIRVM                   ; Use BIOS function like real Mideas
    RET

INIT_SCREEN_SYSTEM:
    ; Initialize screen system for 1 screens
    ; Set current screen to first one
    XOR A
    LD (current_screen_id), A
    CALL LOAD_CURRENT_SCREEN
    RET

INIT_COLLISION_SYSTEM:
    ; Initialize collision detection system
    ; Load behavior maps for collision detection
    ; Setup collision detection variables
    RET

UPDATE_CURRENT_STATE:
    ; Update current game state
    LD A, (current_flow_state)
    CP FLOW_STATE_MAIN_MENU
    JP Z, UPDATE_MAIN_MENU
    CP FLOW_STATE_GAME
    JP Z, UPDATE_GAME
    CP FLOW_STATE_GAME_OVER
    JP Z, UPDATE_GAME_OVER
    RET

UPDATE_MAIN_MENU:
    ; Update main menu logic
    ; Handle menu navigation
    RET

UPDATE_GAME:
    ; Update game logic
    CALL UPDATE_SPRITES       ; Update sprite system
    CALL UPDATE_COLLISIONS    ; Check collisions with behavior maps
    RET

UPDATE_GAME_OVER:
    ; Update game over logic
    ; Handle game over screen
    RET

HANDLE_INPUT:
    ; Handle player input
    CALL GTSTCK
    LD (input_state), A
    RET

UPDATE_GAME_SYSTEMS:
    ; Update only systems that exist in this project
    CALL UPDATE_SPRITES       ; Project has sprites
    CALL UPDATE_COLLISIONS    ; Project has collision layers
    RET

UPDATE_SPRITES:
    ; Update sprite positions and animations
    ; Sprite update logic here
    RET

UPDATE_COLLISIONS:
    ; Check for collisions between sprites and behavior maps
    ; Use BEHAVIOR_TABLE to access behavior data for collision detection
    ; Collision detection logic here
    RET

LOAD_CURRENT_SCREEN:
    ; Load screen based on current_screen_id
    LD A, (current_screen_id)
    CP SCREEN_COUNT
    JR NC, LOAD_DEFAULT_SCREEN   ; If invalid, load default

    ; Use SCREEN_TABLE to get pointer to screen layout
    LD HL, SCREEN_TABLE
    LD E, A
    LD D, 0
    ADD HL, DE
    ADD HL, DE                    ; HL now points to DW screen layout
    LD E, (HL)
    INC HL
    LD D, (HL)                    ; DE = address of screen layout

    ; Copy screen layout to VRAM Name Table at #1800
    EX DE, HL                     ; HL = screen layout address
    LD DE, #1800                  ; Destination: Name Table
    LD BC, 768                    ; 32x24 = 768 bytes
    CALL COPY_TO_VRAM             ; Reuse existing VRAM copy function
    RET

LOAD_DEFAULT_SCREEN:
    ; Clear Name Table with zeros if screen ID is invalid
    LD DE, #1800                  ; VRAM Name Table address
    LD BC, 768                    ; 32x24 = 768 bytes
    XOR A                         ; Fill with zeros
CLEAR_NAME_TABLE_LOOP:
    ; Set VRAM write address
    LD A, E
    OUT (#99), A
    LD A, D
    OR #40
    OUT (#99), A
    ; Write zero
    XOR A
    OUT (#98), A
    ; Increment address
    INC DE
    DEC BC
    LD A, B
    OR C
    JR NZ, CLEAR_NAME_TABLE_LOOP
    RET

COPY_TO_VRAM:
    ; Copy BC bytes from HL to VRAM address DE
    ; Set VRAM write address
    LD A, E
    OUT (#99), A
    LD A, D
    OR #40
    OUT (#99), A
COPY_LOOP:
    LD A, (HL)
    OUT (#98), A
    INC HL
    DEC BC
    LD A, B
    OR C
    JR NZ, COPY_LOOP
    RET

RENDER_FRAME:
    ; Render current frame
    ; Frame rendering logic here
    RET

