; Sprite Pattern References
; bot1: SPRITE_BOT1_* (see individual frame/layer labels above)

; ================================================================
; MSX SCREEN 2 TILE BANK SYSTEM (3 banks of 256 patterns each)
; Bank 0: Lines 0-7   (VRAM Pattern: #0000, Color: #2000)
; Bank 1: Lines 8-15  (VRAM Pattern: #0800, Color: #2800)
; Bank 2: Lines 16-23 (VRAM Pattern: #1000, Color: #3000)
; ================================================================

TILE_COUNT      EQU 2
TILE_BYTES      EQU 8    ; Bytes per character block (TILE_SIZE already defined)

TILE_BRICK1_ID    EQU 0
TILE_GRASS1_ID    EQU 1

; ================================================================
; PATTERN DATA - BANK0 (Lines 0-7)
; VRAM Address: #0000
; Tiles in this bank: 1/256
; ================================================================
TILE_PATTERN_BANK0:
    ; Pattern data for BRICK1 (BANK0)
    DB #00,#7F,#7F,#7F,#00,#FB,#FB,#FB,#00,#BF,#BF,#BF,#00,#FD,#FD,#FD
    DB #00,#7F,#7F,#7F,#00,#FB,#FB,#FB,#00,#BF,#BF,#BF,#00,#FD,#FD,#FD

; ================================================================
; PATTERN DATA - BANK1 (Lines 8-15)
; VRAM Address: #0800
; Tiles in this bank: 1/256
; ================================================================
TILE_PATTERN_BANK1:
    ; Pattern data for GRASS1 (BANK1)
    DB #8D,#AD,#B7,#5E,#A9,#ED,#D0,#ED,#D5,#BC,#1F,#2D,#BC,#9B,#BB,#7B
    DB #4F,#FA,#77,#5A,#1E,#00,#14,#18,#B0,#5F,#8F,#2A,#2F,#83,#A1,#AB

; ================================================================
; PATTERN DATA - BANK2 (Lines 16-23)
; VRAM Address: #1000
; Tiles in this bank: 0/256
; ================================================================
TILE_PATTERN_BANK2:
    ; BANK2 is empty - pattern reuse from Bank 0
    DB #00    ; Empty bank marker

; ================================================================
; COLOR DATA - BANK0 (Lines 0-7)
; VRAM Address: #2000
; Tiles in this bank: 1/256
; ================================================================
TILE_COLOR_BANK0:
    ; Color data for BRICK1 (BANK0)
    DB #61,#61,#61,#61,#61,#61,#61,#91,#61,#B1,#61,#61,#61,#61,#61,#61
    DB #61,#61,#61,#61,#61,#61,#61,#61,#61,#61,#B1,#B1,#61,#61,#61,#61

; ================================================================
; COLOR DATA - BANK1 (Lines 8-15)
; VRAM Address: #2800
; Tiles in this bank: 1/256
; ================================================================
TILE_COLOR_BANK1:
    ; Color data for GRASS1 (BANK1)
    DB #C1,#C1,#C1,#C1,#C1,#C1,#C1,#C1,#C1,#C1,#C1,#C1,#C1,#C1,#C1,#C1
    DB #C1,#C1,#C1,#C1,#C1,#C1,#C1,#C1,#C1,#C1,#C1,#C1,#C1,#C1,#C1,#C1

; ================================================================
; COLOR DATA - BANK2 (Lines 16-23)
; VRAM Address: #3000
; Tiles in this bank: 0/256
; ================================================================
TILE_COLOR_BANK2:
    ; BANK2 colors - can be different from Bank 0 even with same patterns
    DB #0F    ; Empty bank marker (white on transparent)

; MSX Screen 2 Bank Loading Constants
VRAM_PATTERN_BANK0    EQU #0000
VRAM_COLOR_BANK0      EQU #2000
VRAM_PATTERN_BANK1    EQU #0800
VRAM_COLOR_BANK1      EQU #2800
VRAM_PATTERN_BANK2    EQU #1000
VRAM_COLOR_BANK2      EQU #3000

